!> Wraps `zdotu` as a subroutine.
!
! @param {integer} N - number of indexed elements
! @param {Array<complex>} cx - first input array
! @param {integer} strideX - `cx` stride length
! @param {Array<complex>} cy - second input array
! @param {integer} strideY - `cy` stride length
! @param {complex} dot - output variable reference
!<
subroutine zdotusub( N, cx, strideX, cy, strideY, dot )
  implicit none
  ! ..
  ! External functions:
  interface
    complex(kind=kind(0.0d0)) function zdotu( N, cx, strideX, cy, strideY )
      complex(kind=kind(0.0d0)), intent(in) :: cx(*), cy(*)
      integer :: strideX, strideY, N
    end function zdotu
  end interface
  ! ..
  ! Scalar arguments:
  integer :: strideX, strideY, N
  complex(kind=kind(0.0d0)) :: dot
  ! ..
  ! Array arguments:
  complex(kind=kind(0.0d0)), intent(in) :: cx(*), cy(*)
  ! ..
  ! Find the dot product:
  dot = zdotu( N, cx, strideX, cy, strideY )
  return
end subroutine zdotusub
